#!/usr/bin/env python3
"""Offline WAN telemetry incident analyzer.

Reads JSON Lines requests on stdin, writes one JSON response per input line.
Implements exact inference over the set of minimum-fault explanations:
demand recovery, fault-domain attribution, marginal ranges and controller
verdicts.  All arithmetic is exact (integer / rational), no floating point.
"""

import sys
import json
import math
import re
from fractions import Fraction

import z3

# --------------------------------------------------------------------------
# schema validation
# --------------------------------------------------------------------------

NAME_RE = re.compile(r'\A[A-Za-z][A-Za-z0-9_-]{0,31}\Z')
METRICS = ('demand', 'link', 'ingress', 'egress')


class Invalid(Exception):
    """Raised when a request violates the schema."""


def is_name(v):
    return isinstance(v, str) and NAME_RE.match(v) is not None


def as_int(v, lo=None, hi=None):
    if type(v) is not int:
        raise Invalid()
    if lo is not None and v < lo:
        raise Invalid()
    if hi is not not None and v > hi:
        raise Invalid()
    return v


def as_list(v):
    if type(v) is not list:
        raise Invalid()
    return v


def _need(obj, key):
    if not isinstance(obj, dict):
        raise Invalid()
    if key not in obj:
        raise Invalid()
    return obj[key]


def validate(obj):
    """Validate a parsed request; return a normalized structure.

    Raises Invalid on any schema violation.
    """
    if not isinstance(obj, dict):
        raise Invalid()

    rid = obj.get('id')
    if not is_name(rid):
        rid = None

    version = obj.get('version')
    if type(version) is not int or version != 1:
        raise Invalid()

    # ---- nodes -------------------------------------------------------
    nodes = as_list(_need(obj, 'nodes'))
    if not (2 <= len(nodes) <= 12):
        raise Invalid()
    for n in nodes:
        if not is_name(n):
            raise Invalid()
    if len(set(nodes)) != len(nodes):
        raise Invalid()
    node_set = set(nodes)

    # ---- edges -------------------------------------------------------
    edges = as_list(_need(obj, 'edges'))
    if len(edges) > 32:
        raise Invalid()
    edge_ids = set()
    edge_src = {}
    edge_tgt = {}
    edge_cap = {}
    edge_order = []
    for e in edges:
        if not isinstance(e, dict):
            raise Invalid()
        eid = e.get('id')
        if not is_name(eid) or eid in edge_ids:
            raise Invalid()
        src = e.get('source')
        tgt = e.get('target')
        if not isinstance(src, str) or not isinstance(tgt, str):
            raise Invalid()
        if src not in node_set or tgt not in node_set or src == tgt:
            raise Invalid()
        cap = as_int(e.get('capacity'), 0, 1000000)
        edge_ids.add(eid)
        edge_src[eid] = src
        edge_tgt[eid] = tgt
        edge_cap[eid] = cap
        edge_order.append(eid)

    # ---- commodities -------------------------------------------------
    commodities = as_list(_need(obj, 'commodities'))
    if len(commodities) > 12:
        raise Invalid()
    cid_set = set()
    pair_set = set()
    c_order = []
    c_src = {}
    c_tgt = {}
    c_routes = {}
    c_W = {}
    for c in commodities:
        if not isinstance(c, dict):
            raise Invalid()
        cid = c.get('id')
        if not is_name(cid) or cid in cid_set:
            raise Invalid()
        src = c.get('source')
        tgt = c.get('target')
        if not isinstance(src, str) or not isinstance(tgt, str):
            raise Invalid()
        if src not in node_set or tgt not in node_set or src == tgt:
            raise Invalid()
        if (src, tgt) in pair_set:
            raise Invalid()
        routes = as_list(_need(c, 'routes'))
        if not (1 <= len(routes) <= 3):
            raise Invalid()
        parsed = []
        wsum = 0
        for r in routes:
            if not isinstance(r, dict):
                raise Invalid()
            ids = as_list(_need(r, 'edges'))
            if len(ids) < 1:
                raise Invalid()
            w = as_int(_need(r, 'weight'), 1, 8)
            wsum += w
            if wsum > 8:
                raise Invalid()
            for x in ids:
                if not isinstance(x, str) or x not in edge_ids:
                    raise Invalid()
            # path must follow directed endpoints and visit no node twice
            seq = [src]
            for x in ids:
                if edge_src[x] != seq[-1]:
                    raise Invalid()
                seq.append(edge_tgt[x])
            if seq[-1] != tgt:
                raise Invalid()
            if len(set(seq)) != len(seq):
                raise Invalid()
            parsed.append((tuple(ids), w))
        cid_set.add(cid)
        pair_set.add((src, tgt))
        c_order.append(cid)
        c_src[cid] = src
        c_tgt[cid] = tgt
        c_routes[cid] = parsed
        c_W[cid] = wsum

    # ---- domains -----------------------------------------------------
    domains = as_list(_need(obj, 'domains'))
    if len(domains) > 14:
        raise Invalid()
    for d in domains:
        if not is_name(d):
            raise Invalid()
    if len(set(domains)) != len(domains):
        raise Invalid()
    domain_set = set(domains)

    max_faults = as_int(_need(obj, 'max_faults'), 0, len(domains))

    # ---- snapshots ---------------------------------------------------
    snapshots = as_list(_need(obj, 'snapshots'))
    if not (1 <= len(snapshots) <= 4):
        raise Invalid()
    sid_set = set()
    snap_ids = []
    snap_bounds = []
    snap_ctrl = []
    snap_tol = []
    snap_obs = []
    total_obs = 0
    for s in snapshots:
        if not isinstance(s, dict):
            raise Invalid()
        sid = s.get('id')
        if not is_name(sid) or sid in sid_set:
            raise Invalid()
        sid_set.add(sid)

        bounds = as_list(_need(s, 'bounds'))
        if len(bounds) != len(c_order):
            raise Invalid()
        nb = []
        for b in bounds:
            if not isinstance(b, list) or len(b) != 2:
                raise Invalid()
            lo = as_int(b[0], 0, 10000)
            hi = as_int(b[1], 0, 10000)
            if lo > hi:
                raise Invalid()
            nb.append((lo, hi))

        ctrl = as_list(_need(s, 'controller'))
        if len(ctrl) != len(c_order):
            raise Invalid()
        nc = []
        for x in ctrl:
            nc.append(as_int(x, 0, 10000))

        tol = as_int(_need(s, 'tolerance'), 0, 10000)

        observations = as_list(_need(s, 'observations'))
        if len(observations) > 96:
            raise Invalid()
        total_obs += len(observations)
        if total_obs > 256:
            raise Invalid()
        oid_set = set()
        no = []
        for o in observations:
            if not isinstance(o, dict):
                raise Invalid()
            oid = o.get('id')
            if not is_name(oid) or oid in oid_set:
                raise Invalid()
            oid_set.add(oid)
            metric = o.get('metric')
            if not isinstance(metric, str) or metric not in METRICS:
                raise Invalid()
            target = o.get('target')
            if not isinstance(target, str):
                raise Invalid()
            if metric == 'demand':
                if target not in cid_set:
                    raise Invalid()
            elif metric == 'link':
                if target not in edge_ids:
                    raise Invalid()
            else:
                if target not in node_set:
                    raise Invalid()
            lo = as_int(_need(o, 'lower'), -1000000, 1000000)
            hi = as_int(_need(o, 'upper'), -1000000, 1000000)
            if lo > hi:
                raise Invalid()
            dom = o.get('domain')
            if dom is not None:
                if not isinstance(dom, str) or dom not in domain_set:
                    raise Invalid()
            no.append({'metric': metric, 'target': target, 'lower': lo,
                       'upper': hi, 'domain': dom})
        snap_ids.append(sid)
        snap_bounds.append(nb)
        snap_ctrl.append(nc)
        snap_tol.append(tol)
        snap_obs.append(no)

    return {
        'id': rid,
        'nodes': list(nodes),
        'edge_ids': edge_order,
        'edge_src': edge_src,
        'edge_tgt': edge_tgt,
        'edge_cap': edge_cap,
        'cids': c_order,
        'c_src': c_src,
        'c_tgt': c_tgt,
        'c_routes': c_routes,
        'c_W': c_W,
        'domains': list(domains),
        'max_faults': max_faults,
        'snap_ids': snap_ids,
        'bounds': snap_bounds,
        'controller': snap_ctrl,
        'tolerance': snap_tol,
        'observations': snap_obs,
    }


# --------------------------------------------------------------------------
# exact inference
# --------------------------------------------------------------------------

def _fmt_frac(num, den):
    f = Fraction(num, den)
    return '%d/%d' % (f.numerator, f.denominator)


def _eval_int(model, expr):
    v = model.eval(expr, model_completion=True)
    if z3.is_int_value(v):
        return v.as_long()
    if z3.is_rational_value(v):
        num = v.numerator_as_long()
        den = v.denominator_as_long()
        if den == 1:
            return num
        raise ValueError('non integral value')
    raise ValueError('bad model value')


class Analyzer(object):
    def __init__(self, req):
        self.req = req
        self.cids = req['cids']
        self.edge_ids = req['edge_ids']
        self.domains = req['domains']
        self.nC = len(self.cids)
        self.nS = len(req['snap_ids'])
        self.nE = len(self.edge_ids)
        self.cindex = {c: i for i, c in enumerate(self.cids)}
        self.eindex = {e: i for i, e in enumerate(self.edge_ids)}

        # per commodity: total route weight and per edge weight contribution
        W = [req['c_W'][c] for c in self.cids]
        self.W = W
        L = 1
        for w in W:
            L = L * w // math.gcd(L, w)
        self.L = L

        B = [[0] * self.nE for _ in range(self.nC)]
        for ci, c in enumerate(self.cids):
            for (eids, w) in req['c_routes'][c]:
                for e in eids:
                    B[ci][self.eindex[e]] += w
        self.B = B

        # ingress / egress commodity groups
        self.ing = {}
        self.egr = {}
        for ci, c in enumerate(self.cids):
            self.ing.setdefault(req['c_src'][c], []).append(ci)
            self.egr.setdefault(req['c_tgt'][c], []).append(ci)

    # -- metric evaluation in plain python (for witnesses) --------------
    def loads(self, qvec):
        out = [Fraction(0)] * self.nE
        for ci, c in enumerate(self.cids):
            W = self.W[ci]
            for (eids, w) in self.req['c_routes'][c]:
                amt = Fraction(qvec[ci] * w, W)
                for e in eids:
                    out[self.eindex[e]] += amt
        return out

    def metric_value(self, si, o, qvec, loads):
        m = o['metric']
        t = o['target']
        if m == 'demand':
            return Fraction(qvec[self.cindex[t]])
        if m == 'link':
            return loads[self.eindex[t]]
        if m == 'ingress':
            return Fraction(sum(qvec[ci] for ci in self.ing.get(t, ())))
        return Fraction(sum(qvec[ci] for ci in self.egr.get(t, ())))

    def fault_set(self, si, qvec, loads):
        bad = set()
        for o in self.req['observations'][si]:
            v = self.metric_value(si, o, qvec, loads)
            if v < o['lower'] or v > o['upper']:
                bad.add(o['domain'])
        return bad

    # -- z3 model ------------------------------------------------------
    def build(self):
        req = self.req
        solver = z3.Solver()
        self.solver = solver

        q = {}
        for si in range(self.nS):
            for ci in range(self.nC):
                v = z3.Int('q_%d_%d' % (si, ci))
                lo, hi = req['bounds'][si][ci]
                solver.add(v >= lo, v <= hi)
                q[(si, ci)] = v
        self.q = q

        # scaled link loads: X = L * load  (always integral)
        X = {}
        for si in range(self.nS):
            for ei in range(self.nE):
                terms = []
                for ci in range(self.nC):
                    b = self.B[ci][ei]
                    if b:
                        terms.append(b * (self.L // self.W[ci]) * q[(si, ci)])
                e = z3.Sum(terms) if terms else z3.IntVal(0)
                X[(si, ei)] = e
                solver.add(e <= self.L * req['edge_cap'][self.edge_ids[ei]])
        self.X = X

        fault = {}
        for d in self.domains:
            fault[d] = z3.Bool('f_%s' % d)
        self.fault = fault

        active = set()
        for si in range(self.nS):
            for o in req['observations'][si]:
                metric = o['metric']
                lo = o['lower']
                hi = o['upper']
                if metric == 'demand':
                    expr = q[(si, self.cindex[o['target']])]
                elif metric == 'link':
                    expr = X[(si, self.eindex[o['target']])]
                    lo *= self.L
                    hi *= self.L
                elif metric == 'ingress':
                    idx = self.ing.get(o['target'], ())
                    expr = z3.Sum([q[(si, c)] for c in idx]) if idx else z3.IntVal(0)
                else:
                    idx = self.egr.get(o['target'], ())
                    expr = z3.Sum([q[(si, c)] for c in idx]) if idx else z3.IntVal(0)
                inside = z3.And(expr >= lo, expr <= hi)
                if o['domain'] is None:
                    solver.add(inside)
                else:
                    active.add(o['domain'])
                    # a non faulty domain must satisfy all of its observations
                    solver.add(z3.Implies(z3.Not(fault[o['domain']]), inside))
        self.active = [d for d in self.domains if d in active]
        for d in self.domains:
            if d not in active:
                solver.add(z3.Not(fault[d]))

        fs = [fault[d] for d in self.active]
        self.budget = z3.Sum([z3.If(f, 1, 0) for f in fs]) if fs else z3.IntVal(0)
        return solver

    # -- helpers -------------------------------------------------------
    def check_budget(self, t):
        self.solver.push()
        self.solver.add(self.budget <= t)
        r = self.solver.check()
        self.solver.pop()
        return r

    def range_of(self, expr, lo, hi):
        """(min, max) of an integer expression over the current feasible set."""
        solver = self.solver
        a, b = lo, hi
        while a < b:
            mid = (a + b) // 2
            solver.push()
            solver.add(expr <= mid)
            r = solver.check()
            if r == z3.sat:
                v = _eval_int(solver.model(), expr)
                solver.pop()
                if v < mid:
                    b = v
                else:
                    b = mid
            else:
                solver.pop()
                a = mid + 1
        mn = a
        a, b = mn, hi
        while a < b:
            mid = (a + b + 1) // 2
            solver.push()
            solver.add(expr >= mid)
            r = solver.check()
            if r == z3.sat:
                v = _eval_int(solver.model(), expr)
                solver.pop()
                if v > mid:
                    a = v
                else:
                    a = mid
            else:
                solver.pop()
                b = mid - 1
        return mn, a

    # -- main solve ----------------------------------------------------
    def run(self):
        req = self.req
        solver = self.build()

        mf = req['max_faults']
        if self.check_budget(mf) != z3.sat:
            return None  # infeasible

        lo, hi = 0, mf
        while lo < hi:
            mid = (lo + hi) // 2
            if self.check_budget(mid) == z3.sat:
                hi = mid
            else:
                lo = mid + 1
        k = lo
        solver.add(self.budget <= k)

        # demand ranges
        demand_ranges = []
        for si in range(self.nS):
            row = []
            for ci in range(self.nC):
                lo_b, hi_b = req['bounds'][si][ci]
                mn, mx = self.range_of(self.q[(si, ci)], lo_b, hi_b)
                row.append((mn, mx))
            demand_ranges.append(row)

        # link ranges (scaled)
        link_ranges = []
        for si in range(self.nS):
            row = []
            for ei in range(self.nE):
                cap = req['edge_cap'][self.edge_ids[ei]] * self.L
                cap2 = 0
                for ci in range(self.nC):
                    b = self.B[ci][ei]
                    if b:
                        cap2 += b * (self.L // self.W[ci]) * req['bounds'][si][ci][1]
                hi_b = min(cap, cap2)
                mn, mx = self.range_of(self.X[(si, ei)], 0, hi_b)
                row.append((mn, mx))
            link_ranges.append(row)

        # forced / possible domains
        forced = []
        possible = []
        for d in self.active:
            solver.push()
            solver.add(self.fault[d])
            r = solver.check()
            solver.pop()
            if r == z3.sat:
                possible.append(d)
            solver.push()
            solver.add(z3.Not(self.fault[d]))
            r = solver.check()
            solver.pop()
            if r != z3.sat:
                forced.append(d)

        # controller verdicts
        verdicts = []
        for si in range(self.nS):
            ctrl = req['controller'][si]
            tol = req['tolerance'][si]
            agree = []
            disagree = []
            for ci in range(self.nC):
                v = self.q[(si, ci)]
                agree.append(z3.And(v >= ctrl[ci] - tol, v <= ctrl[ci] + tol))
                disagree.append(z3.Or(v < ctrl[ci] - tol, v > ctrl[ci] + tol))
            solver.push()
            solver.add(z3.And(*agree) if agree else z3.BoolVal(True))
            r_ok = solver.check()
            solver.pop()
            solver.push()
            solver.add(z3.Or(*disagree) if disagree else z3.BoolVal(False))
            r_bad = solver.check()
            solver.pop()
            if r_bad != z3.sat:
                verdicts.append('consistent')
            elif r_ok != z3.sat:
                verdicts.append('inconsistent')
            else:
                verdicts.append('undetermined')

        # witness
        solver.push()
        solver.add(z3.BoolVal(True))
        r = solver.check()
        solver.pop()
        if r != z3.sat:
            return None
        model = solver.model()
        wq = []
        for si in range(self.nS):
            row = []
            for ci in range(self.nC):
                row.append(_eval_int(model, self.q[(si, ci)]))
            wq.append(row)

        unique = all(demand_ranges[si][ci][0] == demand_ranges[si][ci][1]
                     for si in range(self.nS) for ci in range(self.nC))
        status = 'unique' if unique else 'ambiguous'

        witness = self.make_witness(wq)

        alternative = None
        if not unique:
            diff = []
            for si in range(self.nS):
                for ci in range(self.nC):
                    diff.append(self.q[(si, ci)] != wq[si][ci])
            solver.push()
            solver.add(z3.Or(*diff) if diff else z3.BoolVal(False))
            r = solver.check()
            if r == z3.sat:
                m2 = solver.model()
                aq = []
                for si in range(self.nS):
                    row = []
                    for ci in range(self.nC):
                        row.append(_eval_int(m2, self.q[(si, ci)]))
                    aq.append(row)
                alternative = self.make_witness(aq)
            solver.pop()

        out = {
            'id': req['id'],
            'status': status,
            'min_faults': k,
            'faults': {'forced': forced, 'possible': possible},
            'snapshots': [],
            'witness': witness,
            'alternative': alternative,
        }
        for si in range(self.nS):
            out['snapshots'].append({
                'id': req['snap_ids'][si],
                'demands': [[demand_ranges[si][ci][0], demand_ranges[si][ci][1]]
                            for ci in range(self.nC)],
                'links': [[_fmt_frac(link_ranges[si][ei][0], self.L),
                           _fmt_frac(link_ranges[si][ei][1], self.L)]
                          for ei in range(self.nE)],
                'verdict': verdicts[si],
            })
        return out

    def make_witness(self, qvec):
        req = self.req
        demands = []
        links = []
        faults = set()
        for si in range(self.nS):
            demands.append(list(qvec[si]))
            loads = self.loads(qvec[si])
            links.append([_fmt_frac(loads[ei].numerator, loads[ei].denominator)
                          for ei in range(self.nE)])
            faults |= self.fault_set(si, qvec[si], loads)
        return {'demands': demands, 'links': links,
                'faults': sorted(faults)}


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------

def handle_line(raw):
    """raw: bytes of one input line (without the trailing newline)."""
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    if text.strip() == '':
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    try:
        obj = json.loads(text, parse_constant=_reject_constant)
    except Exception:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    rid = None
    if isinstance(obj, dict) and is_name(obj.get('id')):
        rid = obj.get('id')
    try:
        req = validate(obj)
    except Invalid:
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    except Exception:
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    try:
        res = Analyzer(req).run()
    except Exception:
        import traceback
        traceback.print_exc(file=sys.stderr)
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    if res is None:
        return {'id': req['id'], 'status': 'infeasible'}
    return res


def _reject_constant(name):
    raise ValueError('non standard JSON constant: %s' % name)


def main():
    out = sys.stdout
    data = sys.stdin.buffer
    for raw in data:
        if raw.endswith(b'\n'):
            raw = raw[:-1]
        try:
            res = handle_line(raw)
        except Exception:
            import traceback
            traceback.print_exc(file=sys.stderr)
            res = {'id': None, 'status': 'error', 'error': 'malformed_json'}
        out.write(json.dumps(res, separators=(',', ':')))
        out.write('\n')
    out.flush()


if __name__ == '__main__':
    main()
PYEOF
